// ========== PARKING LOT (ORCHESTRATOR) ==========
class ParkingLot {
    private static ParkingLot instance;
    private List<Floor> floors;
    private ParkingStrategy strategy;
    private PricingStrategy pricing;
    private final Map<String, Ticket> activeTickets = new ConcurrentHashMap<>();
    private final AtomicInteger counter = new AtomicInteger(1);
    private final ReentrantLock lock = new ReentrantLock();

    private ParkingLot() {}
    public static synchronized ParkingLot getInstance() {
        if (instance == null) instance = new ParkingLot();
        return instance;
    }

    public void initialize(List<Floor> floors, ParkingStrategy ps, PricingStrategy pr) {
        this.floors = floors; this.strategy = ps; this.pricing = pr;
    }

    public Ticket park(Vehicle v) {
        lock.lock();
        try {
            ParkingSpot spot = strategy.findSpot(v.getType(), floors);
            spot.park(v);
            String id = "TKT-" + counter.getAndIncrement();
            Ticket t = new Ticket(id, v, spot);
            activeTickets.put(id, t);
            return t;
        } finally { lock.unlock(); }
    }

    public double unpark(String ticketId) {
        Ticket t = activeTickets.get(ticketId);
        if (t == null) throw new InvalidTicketException("Invalid: " + ticketId);
        t.getSpot().vacate();
        double price = pricing.calculatePrice(t);
        activeTickets.remove(ticketId);
        return price;
    }
}

